import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Linear + ReLU
fused_linear_relu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_linear_relu_kernel(const float* input, const float* weight, const float* bias, float* output, int input_size, int output_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < output_size) {
        float sum = 0.0f;
        for (int i = 0; i < input_size; ++i) {
            sum += input[i] * weight[idx * input_size + i];
        }
        sum += bias[idx];
        output[idx] = fmaxf(0.0f, sum);
    }
}

torch::Tensor fused_linear_relu_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    auto output_size = weight.size(0);
    auto output = torch::zeros({input.size(0), output_size}, torch::kFloat32).cuda();

    const int block_size = 256;
    const int num_blocks = (output_size + block_size - 1) / block_size;

    fused_linear_relu_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), output.data_ptr<float>(), weight.size(1), output_size);

    return output;
}
"""

fused_linear_relu_cpp_source = (
    "torch::Tensor fused_linear_relu_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias);"
)

# Compile the inline CUDA code for fused Linear + ReLU
fused_linear_relu = load_inline(
    name="fused_linear_relu",
    cpp_sources=fused_linear_relu_cpp_source,
    cuda_sources=fused_linear_relu_source,
    functions=["fused_linear_relu_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self, input_size, layer_sizes, output_size):
        super(ModelNew, self).__init__()

        self.layers = nn.ModuleList()
        current_input_size = input_size

        for layer_size in layer_sizes:
            self.layers.append(nn.Linear(current_input_size, layer_size))
            current_input_size = layer_size

        self.output_layer = nn.Linear(current_input_size, output_size)
        self.fused_linear_relu = fused_linear_relu

    def forward(self, x):
        for layer in self.layers:
            weight = layer.weight
            bias = layer.bias
            x = self.fused_linear_relu.fused_linear_relu_cuda(x, weight, bias)

        x = self.output_layer(x)
        return x
